#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>

#define MAX_SIZE 1024

int main(int argc, char *argv[])
{
	int fd;
	char *buf;
	int size;
	int i;
	int count;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		printf("Error opening file %s\n", argv[1]);
		exit(1);
	}

	size = lseek(fd, 0, SEEK_END);
	if (size < 0) {
		printf("Error getting file size\n");
		exit(1);
	}

	buf = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
	if (buf == MAP_FAILED) {
		printf("Error mapping file\n");
		exit(1);
	}

	count = 0;
	for (i = 0; i < size; i++) {
		if (buf[i] == '\n')
			count++;
	}

	ret = 0;
	if (count > 10)
		ret = 1;

	printf("%d\n", ret);

	munmap(buf, size);
	close(fd);

	return 0;
}
