#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>

#define PAGE_SIZE 4096

int main(int argc, char **argv)
{
	int fd;
	char *buf;
	int i;
	int res;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	buf = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	for (i = 0; i < PAGE_SIZE; i++)
		buf[i] = 0;

	res = write(fd, buf, PAGE_SIZE);
	if (res < 0) {
		perror("write");
		exit(1);
	}

	munmap(buf, PAGE_SIZE);
	close(fd);

	return 0;
}
