#include <assert.h>

#define PAGE_SIZE 4096

int main(int argc, char **argv)
{
	int fd;
	void *addr;
	size_t size;
	int ret;

	if (argc!= 2) {
		fprintf(stderr, "Usage: %s <file>\n", argv[0]);
		exit(EXIT_FAILURE);
	}

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		perror("open");
		exit(EXIT_FAILURE);
	}

	size = lseek(fd, 0, SEEK_END);
	if (size < 0) {
		perror("lseek");
		exit(EXIT_FAILURE);
	}

	addr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(EXIT_FAILURE);
	}

	ret = munmap(addr, size);
	if (ret < 0) {
		perror("munmap");
		exit(EXIT_FAILURE);
	}

	ret = close(fd);
	if (ret < 0) {
		perror("close");
		exit(EXIT_FAILURE);
	}

	exit(EXIT_SUCCESS);
}
