int main(int argc, char **argv)
{
	int sock;
	struct hci_dev_info di;
	int dev_id;
	int err;

	if (argc!= 2) {
		printf("Usage: %s <dev_id>\n", argv[0]);
		return 1;
	}

	dev_id = atoi(argv[1]);

	sock = socket(AF_BLUETOOTH, SOCK_RAW, BTPROTO_HCI);
	if (sock < 0) {
		perror("socket");
		return 1;
	}

	memset(&di, 0, sizeof(di));
	di.dev_id = dev_id;

	err = ioctl(sock, HCIGETDEVINFO, (void *) &di);
	if (err < 0) {
		perror("ioctl");
		return 1;
	}

	printf("Device %d: %s\n", dev_id, di.name);

	return 0;
}
