int main(int argc, char **argv)
{
	int fd;
	void *addr;
	struct stat st;
	int i;
	int sum = 0;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	if (fstat(fd, &st) < 0) {
		perror("fstat");
		exit(1);
	}

	addr = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	for (i = 0; i < st.st_size; i++) {
		sum += ((unsigned char *)addr)[i];
	}

	munmap(addr, st.st_size);
	close(fd);

	printf("%d\n", sum);

	return 0;
}
