#define PAGE_SIZE 4096

int main(int argc, char **argv) {
	int fd;
	void *addr;
	int i;
	int ret;
	unsigned char *vec;

	fd = open("/proc/self/maps", O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	addr = mmap(NULL, PAGE_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	vec = malloc(PAGE_SIZE);
	if (vec == NULL) {
		perror("malloc");
		exit(1);
	}

	ret = mincore(addr, PAGE_SIZE, vec);
	if (ret < 0) {
		perror("mincore");
		exit(1);
	}

	for (i = 0; i < PAGE_SIZE; i++) {
		if (vec[i] == 1) {
			printf("1\n");
			break;
		}
	}

	munmap(addr, PAGE_SIZE);
	close(fd);
	free(vec);

	return 0;
}
