int main(int argc, char *argv[])
{
	char *buf;
	int fd;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return 1;
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		return 1;
	}

	buf = mmap(NULL, BUF_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
