	}

	ret = strcmp(buf, "1");
	if (ret == 0)
		printf("1\n");
	else if (ret == 1)
		printf("0\n");
	else
		printf("not sure\n");

	munmap(buf, BUF_SIZE);
	close(fd);

	return 0;
}
