			return 1;
		}

		cwe_list[cwe_count++] = cwe_id;
	}

	printf("[");
	for (i = 0; i < cwe_count; i++) {
		if (i > 0)
			printf(", ");
		printf("\"%s\"", cwe_list[i]);
	}
	printf("]\n");

	return 0;
}
