#define BUF_SIZE 1024

int main(int argc, char *argv[])
{
	int fd, ret;
	char buf[BUF_SIZE];
	char *cwe_list[5];
	int i;

	if (argc!= 2) {
		printf("Usage: %s <device>\n", argv[0]);
		return -1;
	}

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		printf("Failed to open %s\n", argv[1]);
		return -1;
	}

	memset(buf, 0, BUF_SIZE);
	ret = read(fd, buf, BUF_SIZE);
	if (ret < 0) {
		printf("Failed to read from %s\n", argv[1]);
		close(fd);
		return -1;
	}

	if (strncmp(buf, "0x", 2)!= 0) {
		printf("Invalid IOCTL command\n");
		close(fd);
		return -1;
	}

	cwe_list[0] = strtok(buf, " ");
	for (i = 1; i < 5; i++)
		cwe_list[i] = strtok(NULL, " ");

	printf("[");
	for (i = 0; i < 5; i++) {
		if (i!= 0)
			printf(", ");
		printf("\"%s\"", cwe_list[i]);
	}
	printf("]\n");

	close(fd);
	return 0;
}
