        *cwe_str_ptr = '\0';
        cwe_str_ptr++;
        cwe_num++;
    }

    printf("[");
    for (i = 0; i < cwe_num; i++) {
        if (i!= 0) {
            printf(", ");
        }
        printf("\"CWE-%s\"", cwe_list[i]);
    }
    printf("]\n");

    return 0;
}
